use verus::*;

// Specification and implementation of reverse function
// Given input vector `a`, returns a new vector `a_rev` that is the reverse of `a`.
// Ensures:
// - Same length as input
// - For every index i in [0, a.len()), a[i] == a_rev[a.len()-1 - i]
verus! {
    fn reverse(a: &Vec<i32>) -> (a_rev: Vec<i32>)
        ensures
            a_rev.len() == a.len()
            && forall(|i: usize| i < a.len() ==> a[i] == a_rev[a.len() - 1 - i])
    {
        let n = a.len();
        let mut a_rev = Vec::with_capacity(n);
        // invariant: a_rev.len() == i && forall j in [0,i), a[j] == a_rev[n-1-j]
        let mut i: usize = 0;
        while i < n
            invariant
                i <= n
                && a_rev.len() == i
                && forall(|j: usize| j < i ==> a[j] == a_rev[n - 1 - j])
            decreases n - i
        {
            // push a[n-1 - i]
            let idx = n - 1 - i;
            a_rev.push(a[idx]);
            i += 1;
        }
        a_rev
    }
}